-- Portable relational starter schema (simplified)
CREATE TABLE requirements (requirement_id VARCHAR(20) PRIMARY KEY, epic_id VARCHAR(20), domain VARCHAR(40), title VARCHAR(255), description TEXT, requirement_type VARCHAR(40), priority VARCHAR(10), source_document_id VARCHAR(20), source_section VARCHAR(255), status VARCHAR(40), release VARCHAR(20), owner VARCHAR(100), version VARCHAR(20), effective_date DATE, approval_status VARCHAR(40));
CREATE TABLE acceptance_criteria (acceptance_criterion_id VARCHAR(20) PRIMARY KEY, requirement_id VARCHAR(20), criterion TEXT, criterion_type VARCHAR(40), status VARCHAR(40));
CREATE TABLE test_cases (test_case_id VARCHAR(20) PRIMARY KEY, requirement_id VARCHAR(20), domain VARCHAR(40), title VARCHAR(255), test_type VARCHAR(40), preconditions TEXT, steps TEXT, expected_result TEXT, automation_status VARCHAR(40), status VARCHAR(40), owner VARCHAR(100));
CREATE TABLE traceability_links (link_id VARCHAR(20) PRIMARY KEY, requirement_id VARCHAR(20), acceptance_criterion_id VARCHAR(20), test_case_id VARCHAR(20), link_type VARCHAR(40), status VARCHAR(40));
CREATE TABLE test_executions (execution_id VARCHAR(20) PRIMARY KEY, test_case_id VARCHAR(20), release VARCHAR(20), environment VARCHAR(20), executed_at TIMESTAMP, outcome VARCHAR(20), duration_seconds INT, build_id VARCHAR(40), evidence_uri VARCHAR(255));
CREATE TABLE defects (defect_id VARCHAR(20) PRIMARY KEY, test_case_id VARCHAR(20), requirement_id VARCHAR(20), release VARCHAR(20), severity VARCHAR(10), status VARCHAR(40), summary TEXT, detected_in_build VARCHAR(40), owner_team VARCHAR(100));
